  v("energyWindow", p.energyWindow);
  v("maxRotatableBonds", p.maxRotatableBonds);
  v("timeBudgetMs", p.timeBudgetMs);
  v("sampleTrivialRotors", p.sampleTrivialRotors);
  v("wholeAcyclicFragments", p.wholeAcyclicFragments);

  // --- fragment embedding ---
  v("embedding.numConfsPerFragment", p.embedding.numConfsPerFragment);
  v("embedding.fragmentEmbedMode", p.embedding.fragmentEmbedMode);
  v("embedding.minimizeMode", p.embedding.minimizeMode);
  v("embedding.ffVariant", p.embedding.ffVariant);
  v("embedding.shrugDisplacement", p.embedding.shrugDisplacement);
  v("embedding.minimizeGradTol", p.embedding.minimizeGradTol);
  v("embedding.perClassEmbedding", p.embedding.perClassEmbedding);

  v("outputRanking", p.outputRanking);
  v("rankByBasinEnergy", p.rankByBasinEnergy);
  v("labelFFVariant", p.labelFFVariant);

  // --- joiner (build) ---
  v("joiner.ffVariant", p.joiner.ffVariant);
  v("joiner.interFragVdwCutoff", p.joiner.interFragVdwCutoff);
  v("joiner.fragShrugDisplacement", p.joiner.fragShrugDisplacement);
  v("joiner.fragShrugForceConst", p.joiner.fragShrugForceConst);
  v("joiner.useFullFFScorer", p.joiner.useFullFFScorer);

  // --- search: common ---
  v("search.searchMode", p.search.searchMode);
  v("search.rootSeeds", p.search.rootSeeds);
  v("search.fragConfBranch", p.search.fragConfBranch);
  v("search.finalSymmetryDedup", p.search.finalSymmetryDedup);
