  v("search.thompson.maxBudget", p.search.thompson.maxBudget);
  v("search.thompson.refineSteps", p.search.thompson.refineSteps);
  v("search.thompson.refineStepDeg", p.search.thompson.refineStepDeg);
  v("search.thompson.refinePasses", p.search.thompson.refinePasses);
  v("search.thompson.maxConfs", p.search.thompson.maxConfs);
