// ---- writer -----------------------------------------------------------------
struct Writer {
  std::ostream &os;
  void write(const char *k, const std::string &val) {
    os << k << " = " << val << "\n";
  }
  void operator()(const char *k, bool b) { write(k, b ? "true" : "false"); }
  // -1 = AUTO, 0 = DISABLED (see Utils/ParamSentinels.h) -- both serialise as
  // plain numbers, so there is no token to special-case in either direction.
  void operator()(const char *k, unsigned int n) { write(k, std::to_string(n)); }
  void operator()(const char *k, int n) { write(k, std::to_string(n)); }
  void operator()(const char *k, long n) { write(k, std::to_string(n)); }
  void operator()(const char *k, double d) {
    std::ostringstream ss;
    ss.precision(10);
    ss << d;
    write(k, ss.str());
  }
  void operator()(const char *k, const std::string &s) { write(k, s); }
  void operator()(const char *k, FragmentEmbedMode m) { write(k, toStr(m)); }
  void operator()(const char *k, FragmentMinimize m) { write(k, toStr(m)); }
  void operator()(const char *k, RigidRotorSearchMode m) { write(k, toStr(m)); }
  void operator()(const char *k, JunctionBasinAngles m) { write(k, toStr(m)); }
  void operator()(const char *k, OutputRanking m) { write(k, toStr(m)); }
  void operator()(const char *k, OutputSelection m) { write(k, toStr(m)); }
  void operator()(const char *k, RotorWeighting m) { write(k, toStr(m)); }
  void operator()(const char *k, AtropisomerSampling m) { write(k, toStr(m)); }
};

struct Reader {
  std::map<std::string, std::string> &kv;  // remaining unconsumed keys
  std::string &err;

  //! pop the value for `k` if present; false when absent or an error was
  //! already set.
  bool take(const char *k, std::string &out) {
    if (!err.empty()) return false;
    auto it = kv.find(k);
    if (it == kv.end()) return false;
    out = it->second;
    kv.erase(it);
    return true;
  }
  void bad(const char *k, const std::string &v, const char *want) {
    err = std::string("bad value for '") + k + "' = '" + v + "' (expected " +
          want + ")";
  }

  void operator()(const char *k, bool &b) {
    std::string v;
    if (!take(k, v)) return;
    if (v == "true" || v == "1" || v == "yes")
      b = true;
    else if (v == "false" || v == "0" || v == "no")
      b = false;
    else
      bad(k, v, "true/false");
  }
  template <class Int>
  void readInt(const char *k, Int &n, const char *want) {
    std::string v;
    if (!take(k, v)) return;
    try {
      size_t pos = 0;
      long long parsed = std::stoll(v, &pos);
      if (pos != v.size()) {
        bad(k, v, want);
        return;
      }
      n = static_cast<Int>(parsed);
    } catch (...) {
      bad(k, v, want);
    }
  }
  void operator()(const char *k, unsigned int &n) {
    readInt(k, n, "an integer");
  }
  void operator()(const char *k, int &n) { readInt(k, n, "an integer"); }
  void operator()(const char *k, long &n) { readInt(k, n, "an integer"); }
  void operator()(const char *k, double &d) {
    std::string v;
    if (!take(k, v)) return;
    try {
      size_t pos = 0;
      d = std::stod(v, &pos);
      if (pos != v.size()) bad(k, v, "a number");
    } catch (...) {
      bad(k, v, "a number");
    }
  }
  void operator()(const char *k, std::string &s) {
    std::string v;
    if (take(k, v)) s = v;  // empty allowed
  }
  template <class Enum>
  void readEnum(const char *k, Enum &m, const char *want) {
    std::string v;
    if (!take(k, v)) return;
    if (!fromStr(v, m)) bad(k, v, want);
  }
  void operator()(const char *k, FragmentEmbedMode &m) {
    readEnum(k, m, "DG|ETKDG");
  }
  void operator()(const char *k, FragmentMinimize &m) {
    readEnum(k, m, "None|Full|Score|ShrugScore");
  }
  void operator()(const char *k, JunctionBasinAngles &m) {
    readEnum(k, m, "All|None|ChainOnly");
  }
  void operator()(const char *k, RigidRotorSearchMode &m) {
    readEnum(
        k, m,
        "Auto|Tree|Thompson|Systematic|Merged");
  }
  void operator()(const char *k, OutputRanking &m) {
    readEnum(k, m, "FFEnergy|InterFragScore");
  }
  void operator()(const char *k, OutputSelection &m) {
    readEnum(k, m, "Energy|Diverse|Stratify");
  }
  void operator()(const char *k, RotorWeighting &m) {
    readEnum(k, m, "MovingAtoms|Uniform|Inverted");
  }
  void operator()(const char *k, AtropisomerSampling &m) {
    readEnum(k, m, "Basin|Frozen");
  }
};

std::string trim(const std::string &s) {
  size_t a = 0, b = s.size();
  while (a < b && std::isspace(static_cast<unsigned char>(s[a]))) ++a;
  while (b > a && std::isspace(static_cast<unsigned char>(s[b - 1]))) --b;
  return s.substr(a, b - a);
}

