void writeFragmentConfGenParams(std::ostream &os,
                                const FragmentConfGenParams &p) {
  os << "# FragmentConfGen parameters (key = value; '#' comments; dotted sub-struct keys).\n"
     << "# torsionSampler and embedder are runtime-wired, not serialized here.\n";
  Writer w{os};
  visitFields(p, w);
}

std::string readFragmentConfGenParams(std::istream &is,
                                      FragmentConfGenParams &p) {
  std::map<std::string, std::string> kv;
  std::string line;
  int lineNo = 0;
  while (std::getline(is, line)) {
    ++lineNo;
    // strip comments (everything from an unquoted '#')
    auto hash = line.find('#');
    if (hash != std::string::npos) line = line.substr(0, hash);
    std::string t = trim(line);
    if (t.empty()) continue;
    auto eq = t.find('=');
    if (eq == std::string::npos) {
      return "line " + std::to_string(lineNo) +
             ": expected 'key = value', got '" + t + "'";
    }
    std::string key = trim(t.substr(0, eq));
    std::string val = trim(t.substr(eq + 1));
    if (key.empty()) {
      return "line " + std::to_string(lineNo) + ": empty key";
    }
    if (!kv.emplace(key, val).second) {
      return "duplicate key '" + key + "' (line " + std::to_string(lineNo) +
             ")";
    }
  }
  std::string err;
  Reader r{kv, err};
  visitFields(p, r);
  if (!err.empty()) return err;
  // Keys that USED to exist.  A retired key must not invalidate a whole stored
  // parameter block -- a serialized library outlives the parameter that was
  // dropped, and failing the parse silently reverts it to defaults, losing the
  // settings it was actually built with.  Genuine typos still fail.
  static const std::set<std::string> retired = {
      "search.thompson.flatContext",
      "diagnostics.FRAGLIB_TRACE",  // renamed to EMBEDDER_TRACE
      "search.autoSystematicMinRotors",
      "search.autoSystematicMaxRotors",
  };
  for (auto it = kv.begin(); it != kv.end();) {
    if (retired.count(it->first)) {
      BOOST_LOG(rdWarningLog)
          << "ignoring retired parameter '" << it->first << "'" << std::endl;
      it = kv.erase(it);
    } else {
      ++it;
    }
  }
  if (!kv.empty()) return "unknown key '" + kv.begin()->first + "'";
  return {};
}

const char *searchModeName(RigidRotorSearchMode m) { return toStr(m); }

FragmentConfGenParams resolvedFragmentConfGenParams(
    const FragmentConfGenParams &p) {
  FragmentConfGenParams r = p;

  // --- derivations that FragmentConfGen::build applies before running anything
  // ------------- one force field for the whole pipeline (see getEmbedderParams)
  r.embedding.ffVariant = r.joiner.ffVariant;
  // the search beam runs on a WIDER window than the output keep-window
  r.search.energyWindow = r.energyWindow > 0 ? r.energyWindow * 2.5 : 25.0;
  if (r.labelFFVariant.empty()) r.labelFFVariant = r.joiner.ffVariant;

  // --- AUTO sentinels, resolved exactly as each search resolves them
  // ------------------------
  const double divFallback = r.search.diversityRmsThresh > 0.0
                                 ? r.search.diversityRmsThresh
                                 : 0.5;
  r.search.systematic.finalRms =
      resolveAuto(r.search.systematic.finalRms, divFallback);
  r.search.systematic.nodeRms =
      resolveAuto(r.search.systematic.nodeRms, r.search.systematic.finalRms);
  for (auto &kv : r.embedding.classParams) {
    kv.second.minimizeMaxIters =
        resolveAuto(kv.second.minimizeMaxIters, r.embedding.minimizeMaxIters);
  }
  return r;
}

std::string fragmentConfGenParamsToString(const FragmentConfGenParams &p) {
  std::ostringstream os;
  writeFragmentConfGenParams(os, p);
  return os.str();
}

std::string fragmentConfGenParamsFromString(const std::string &text,
                                            FragmentConfGenParams &p) {
  std::istringstream is(text);
  return readFragmentConfGenParams(is, p);
}

